def rust_code_without_comments(source):
 out=[];index=0;length=len(source)
 def masked(start,end):return ''.join('\n' if char=='\n' else ' ' for char in source[start:end])
 while index<length:
  if source.startswith('//',index):
   end=source.find('\n',index)
   if end<0:out.append(masked(index,length));break
   out.append(masked(index,end));out.append('\n');index=end+1;continue
  if source.startswith('/*',index):
   start=index;depth=1;index+=2
   while index<length and depth:
    if source.startswith('/*',index):depth+=1;index+=2
    elif source.startswith('*/',index):depth-=1;index+=2
    else:index+=1
   out.append(masked(start,index));continue
  raw_prefix=re.match(r'(?:br|cr|r)(#*)"',source[index:])
  if raw_prefix is not None:
   terminator='"'+raw_prefix.group(1);start=index;index+=raw_prefix.end();end=source.find(terminator,index)
   index=length if end<0 else end+len(terminator);out.append(masked(start,index));continue
  if source[index]=='"':
   start=index;index+=1
   while index<length:
    if source[index]=='\\':index+=2
    elif source[index]=='"':index+=1;break
    else:index+=1
   index=min(index,length);out.append(masked(start,index));continue
  out.append(source[index]);index+=1
 return ''.join(out)
